function valid(t,o){return Number.isFinite(t)&&t>=0&&t<1&&[o.x??224,o.y??78,o.width??320,o.height??180].every(Number.isFinite)&&(o.width??320)>0&&(o.height??180)>0&&(o.width??320)<=2048&&(o.height??180)<=2048;}
function draw(ctx,name,t,o){const f=ATLAS.frames[name][Math.round(clamp(t)*(ATLAS.frames[name].length-1))];const w=Math.floor(o.width??320),h=Math.floor(o.height??180),ox=Math.round((o.x??224)-ATLAS.size/2),oy=Math.round((o.y??78)-ATLAS.size/2);let count=0;for(let i=0;i<f.length;i+=4){let x=ox+f[i],y=oy+f[i+1],r=Math.min(w,x+f[i+2]),l=Math.max(0,x);if(y<0||y>=h||r<=l)continue;ctx.fillStyle=ATLAS.palette[f[i+3]];ctx.fillRect(l,y,r-l,1);count+=r-l;}return count;}
