export function chronoEchoState(t,o={}){if(!valid(t,o)||o.reducedMotion||t<=.05||t>=.75)return [];let v=smooth((t-.05)/.18)*smooth((.75-t)/.35);return [3,2,1].map((k)=>({dx:Math.round(k*7*v),dy:Math.round(-k*3*v),opacity:v*(.27-.055*k)}));}
export function drawChronoRewind(ctx,t,o={}){if(!valid(t,o))return 0;const layer=o.layer??'both';if(o.reducedMotion){if(t<.2||t>.72)return 0; t=.58;}let n=0;if(layer==='rear'||layer==='both')n+=draw(ctx,'rewindRear',t,o);if(layer==='front'||layer==='both')n+=draw(ctx,'rewindFront',t,o);return n;}
